	"greatwallpaper": {
		author: "Margaret J. Geller and John P. Huchra",
		year: 1989,
		title: "Mapping the Universe",
		url: "https://doi.org/10.1126/science.246.4932.897",
		alternativetitle: "The Great Wall (Geller & Huchra 1989)"
	},
	/* The cosmological principle: on a large-enough scale the universe is
	 * homogeneous and isotropic. Usually traced back to Newton's Principia
	 * (1687), where the universe is treated as uniform and the same laws are
	 * held to hold throughout. */
	"cosmologicalprinciple": {
		author: "Isaac Newton",
		year: 1687,
		title: "Philosophiæ Naturalis Principia Mathematica",
		url: "https://www.gutenberg.org/ebooks/28233",
		alternativetitle: "The cosmological principle (Newton, Principia 1687)"
	},
	/* Lynds (1971) — first recorded the Lyman-alpha forest: the many narrow
	 * Lyman-alpha absorption lines in the spectrum of the high-redshift quasar
	 * 4C 05.34, produced by intergalactic gas along the line of sight.
	 * ApJ 164: L73–L78. */
	"lymanalphaforest": {
		author: "Roger Lynds",
		year: 1971,
		title: "The Absorption-Line Spectrum of 4C 05.34",
		url: "https://doi.org/10.1086/180695",
		alternativetitle: "The Lyman-alpha forest (Lynds 1971)"
	},
	/* Roger Shepard's 1987 "universal law of generalization": the probability
	 * that a response learned to one stimulus generalizes to another falls off
	 * exponentially with the distance between the two in a psychological
	 * space. Original: Science 237(4820): 1317–1323. */
	"shepard1987universal": {
		author: "Roger N. Shepard",
		year: 1987,
		title: "Toward a Universal Law of Generalization for Psychological Science",
		url: "https://legacy.voteview.com/pdf/Shepard_1987.pdf",
		alternativetitle: "The Universal Law of Generalization"
	},
	/* He, Tsai & Ward (2023) — "Side Effects of Learning from Low-dimensional
	 * Data Embedded in a Euclidean Space". Training pins the learned function
	 * down along a low-dimensional data manifold while leaving the normal
	 * (void) directions free, fixed by initialization; noise in the codimension
	 * regularizes them at sample cost N ~ sigma^{-2} and slow convergence.
	 * Research in the Mathematical Sciences 10(1): 13. arXiv:2203.00614. */
	"he2023sideeffects": {
		author: "Juncai He, Yen-Hsi Richard Tsai, Rachel Ward",
		year: 2023,
		title: "Side Effects of Learning from Low-Dimensional Data Embedded in a Euclidean Space",
		journal: "Research in the Mathematical Sciences",
		volume: 10,
		number: 1,
		url: "https://doi.org/10.1007/s40687-023-00378-y",
		alternativetitle: "He, Tsai & Ward, side effects of low-dimensional learning (2023)"
	},
